from threading import Lock


class BalancePair:
    def __init__(self, left: int, right: int) -> None:
        left, right = int(left), int(right)
        if left < 0 or right < 0:
            raise ValueError("negative opening balance")
        self._balances = [left, right]
        self._lock = Lock()

    def transfer(self, amount: int) -> bool:
        amount = int(amount)
        with self._lock:
            return self._move(amount)

    def snapshot(self) -> tuple[int, int]:
        with self._lock:
            return self._balances[0], self._balances[1]

    def _move(self, amount: int) -> bool:
        left, right = self._balances
        if amount > left or amount < -right:
            return False
        self._balances[0] = left - amount
        self._balances[1] = right + amount
        return True

