class PlainInt(int):
    pass


class SmallInt(IntEnum):
    NEGATIVE = -1
    ZERO = 0
    ONE = 1
    TWO = 2


def _sequential(mod: ModuleType) -> bool:
    huge = 10 ** 150
    openings = [0, 1, 2, 17, huge, True, False, PlainInt(3),
                SmallInt.ZERO, SmallInt.TWO]
    for left, right in product(openings, repeat=2):
        pair = mod.BalancePair(left, right)
        state = (int(left), int(right))
        if tuple(pair.snapshot()) != state:
            return True
        amounts = [0, False, True, PlainInt(-1), SmallInt.ONE,
                   SmallInt.NEGATIVE, left, -int(right), huge, -huge,
                   huge + 1, -huge - 1, 1, -1]
        for amount in amounts:
            before = state
            accepted = -before[1] <= int(amount) <= before[0]
            result = pair.transfer(amount)
            if result is not accepted:
                return True
            if accepted:
                state = (before[0] - int(amount), before[1] + int(amount))
            if tuple(pair.snapshot()) != state:
                return True
        for amount in [state[0] + 1, -state[1] - 1, 0, -state[1]]:
            accepted = -state[1] <= amount <= state[0]
            if pair.transfer(amount) is not accepted:
                return True
            if accepted:
                state = (state[0] - amount, state[1] + amount)
            if tuple(pair.snapshot()) != state:
                return True

    for left, right in [(-1, 0), (0, -1), (-huge, huge),
                        (huge, -huge), (-1, -1), (SmallInt.NEGATIVE, 2)]:
        try:
            mod.BalancePair(left, right)
        except Exception:
            continue
        return True

    first = mod.BalancePair(7, 11)
    saved = first.snapshot()
    second = mod.BalancePair(13, 19)
    if tuple(first.snapshot()) != (7, 11):
        return True
    if first.transfer(7) is not True:
        return True
    if tuple(second.snapshot()) != (13, 19) or tuple(saved) != (7, 11):
        return True
    if second.transfer(-19) is not True:
        return True
    return tuple(first.snapshot()) != (0, 18)


def _serial_possible(initial, history, final) -> bool:
    count = len(history)
    predecessors = []
    for _, _, start, _ in history:
        predecessors.append(sum(1 << j for j, entry in enumerate(history)
                                if entry[3] < start))

    def search(state, used):
        if used == (1 << count) - 1:
            return state == final
        for i, (amount, result, _, _) in enumerate(history):
            bit = 1 << i
            if used & bit or predecessors[i] & ~used:
                continue
            if amount is None:
                if tuple(result) != state:
                    continue
                after = state
            else:
                accepted = -state[1] <= amount <= state[0]
                if result is not accepted:
                    continue
                after = (state[0] - amount, state[1] + amount) if accepted else state
            if search(after, used | bit):
                return True
        return False

