import sqlite3

MAX_BALANCE = (1 << 63) - 1


class Ledger:
    def __init__(self, debit: int, credit: int):
        if not (0 <= debit <= MAX_BALANCE and 0 <= credit <= MAX_BALANCE):
            raise ValueError("balance out of range")
        self._db = sqlite3.connect(":memory:", isolation_level="DEFERRED")
        self._db.execute(
            "CREATE TABLE accounts (id INTEGER PRIMARY KEY, balance INTEGER "
            "NOT NULL CHECK(typeof(balance) = 'integer' AND balance >= 0))"
        )
        self._db.execute("CREATE TABLE transfers (reference TEXT NOT NULL UNIQUE)")
        with self._db:
            self._db.executemany(
                "INSERT INTO accounts VALUES (?, ?)", ((0, debit), (1, credit))
            )

    def snapshot(self) -> tuple[int, int, tuple[str, ...]]:
        balances = self._db.execute("SELECT balance FROM accounts ORDER BY id").fetchall()
        references = self._db.execute(
            "SELECT reference FROM transfers ORDER BY rowid"
        ).fetchall()
        return balances[0][0], balances[1][0], tuple(row[0] for row in references)

    def transfer(self, amount: int, reference: str) -> tuple[int, int, tuple[str, ...]]:
        with self._db:
            return self._post(amount, reference)

    def _post(self, amount: int, reference: str) -> tuple[int, int, tuple[str, ...]]:
        if amount < 0:
            raise ValueError("negative transfer")
        self._db.execute("UPDATE accounts SET balance = balance - ? WHERE id = 0", (amount,))
        self._db.execute("UPDATE accounts SET balance = balance + ? WHERE id = 1", (amount,))
        self._db.execute("INSERT INTO transfers VALUES (?)", (reference,))
        return self.snapshot()

    def close(self) -> None:
        self._db.close()

