from collections.abc import Callable


class CleanupQueue:
    def __init__(self) -> None:
        self._pending: list[object] = []

    def enqueue(self, resource: object) -> None:
        self._pending.append(resource)

    @property
    def pending(self) -> tuple[object, ...]:
