def _ordinal(value: date) -> int:
    year = value.year - 1
    before = (0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334)
    leap = value.year % 4 == 0 and (value.year % 100 != 0 or value.year % 400 == 0)
