def preview_reservations(
    stock: dict[str, int], requests: tuple[tuple[str, int], ...]
) -> dict[str, int]:
    working = stock
    if any(available < 0 for available in working.values()):
        raise ValueError("negative stock")
    for sku, quantity in requests:
